mapper.select:
select * from (
    select

        (NVL(day_plan_qty, 0) + NVL(night_plan_qty, 0)) as daily_total_qty,
        b.MONTH_PLAN_QTY as month_plan,
        CEIL(b.MONTH_REMAIN_QTY) as month_plan_os
    from t_cd90_assist_schedule a
    LEFT JOIN (
        SELECT MATERIAL_CODE,MONTH_PLAN_QTY,MONTH_REMAIN_QTY
        FROM T_CD90_MONTH_PLAN_SURPLUS
        WHERE del_flag='0'
        and YEAR=#{year,jdbcType=VARCHAR}
        and MONTH=#{month,jdbcType=VARCHAR}
    ) b on a.CLOTH_CODE=b.MATERIAL_CODE
    where a.del_flag='0'
    and a.schedule_date = #{scheduleDate,jdbcType=DATE}

        and INSTR(a.big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0


        and INSTR(a.cloth_code, #{clothCode,jdbcType=VARCHAR}) > 0

    and instr(','||a.machine_id||',', ','||#{machineId}||',')>0
    and a.IS_RELEASE = #{isRelease}
    order by (case when instr(machine_id,',') > 0 then machine_id when machine_id is null or machine_id = '' then '0' else '-1' end) desc/*多个机台 和 没有机台的排在前面*/,
    a.big_roll_code,a.cloth_code asc
) t

    order by ${orderStr}
